;; make dot "set32";org 0x2000MAKE_BC_SPACES      equ 0x0030RECLAIM_BC_SPACES   equ 0x19e8IDE_BASIC           equ 0x01c0M_P3DOS             equ 0x94    ; Allocate space for the tokens    ld bc, .len    rst 0x18    dw MAKE_BC_SPACES    ld (.addr_s),de        ; Copy the tokens to the allocated space    ld hl,.toks    ld bc,.len    ldir    ; Execute the tokenized BASIC code    ld de,IDE_BASIC    ld c,0          ; Page in BANK 0    exx    ld hl,(.addr_s)    exx    rst 0x08    db M_P3DOS    ; Free the allocated space    ld hl, (.addr_s)    ld bc, (.len)    rst 0x18    dw RECLAIM_BC_SPACES    ret.toks db 0xa3, 0xc2, 0x25, "32", ":", 0xfb, 0x0d ; SPECTRUM CHR$ %32:CLS.len equ $ - .toks.addr_s dw 0